INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, published_at) VALUES ('2.72.0', 2072000, 'windows', 'releases/CosmicPlatformer-Setup-2.72.0.exe', 'CosmicPlatformer-Setup-2.72.0.exe', 149573661, '52fd6d8f20169bf0beb1398744c2f3e65debe7998f2051c85101cf8256caacdf', 'Version 2.72.0 :
• Attaque dirigée : maintenez Haut en attaquant pour frapper au-dessus de Nova, au sol comme en l''air ; en l''air, maintenez Bas pour frapper en dessous. Au sol, Bas reste « s''accroupir » (l''attaque frappe alors devant, comme avant) et, avec la Frappe sismique, Bas + Attaque en l''air reste la frappe sismique. Ces coups touchent les ennemis (mêmes dégâts, même recul) et les objets cassables comme le coup vers l''avant, avec leurs propres animations et leur arc de lame ; un coup vers le bas en l''air rebondit toujours sur l''ennemi touché et rend les sauts en l''air, comme avant. La direction est celle choisie au début du coup. Expliqué dans Paramètres › Clavier / souris et Manette, et dans le tutoriel.
• Records et classements conservés : rien n''est remis à zéro. Les replays enregistrés avant cette version se rejouent exactement comme avant (avec les règles de leur époque) ; les nouveaux replays notent la version de la simulation qui les a joués. Les combinaisons créées en ligne gardent leur planche : pendant un coup vers le haut ou vers le bas, Nova y montre le coup vers l''avant.
• La présentation du jeu (README) et sa documentation montrent maintenant les raids de clan et la coopération en mini-films tournés dans le jeu : trois joueurs ensemble sur un niveau EXTRÊME, les combats contre Pyroclast et Graviton, l''apparition d''Asterion et la carte du titan ; chaque page de la documentation a ses images et son lien « ← Retour ».', '2026-11-18T17:14:57.924Z') ON CONFLICT (version) DO NOTHING;
